def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0
    inc = arr[:]
    dec = arr[:]
    for i in range(n):
        for j in range(i):
            if arr[i] > arr[j]:
                inc[i] = max(inc[i], inc[j] + arr[i])
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                dec[i] = max(dec[i], dec[j] + arr[i])
    return max(inc[i] + dec[i] - arr[i] for i in range(n))

